def collect(specs, scopes, root, request_id, execution_context, complete=True, known=()):
    """([Artifact], [(code, artifact_id, message)]) for the artifacts an adapter declared.

    Every path is checked against the permitted scopes before the file is opened, so a path escape
    or a symlink is refused rather than hashed. A derived artifact inherits the origin's capture
    context; a canonical one records the context this execution observed.
    """
    by_id = {a.artifact_id: a for a in known}
    out, problems = ([], [])
    for spec in specs:
        reason = tp.unsafe_reason(scopes, spec.path)
        if reason:
            problems.append(('UNSAFE_ARTIFACT_PATH', spec.artifact_id, reason))
            continue
        if tp.in_records(root, spec.path):
            problems.append(('UNSAFE_ARTIFACT_PATH', spec.artifact_id, f'{spec.path}: tool execution never writes into the canonical record area {tp.RECORDS_DIR}/'))
            continue
        path = Path(spec.path)
        if not path.is_file():
            problems.append(('ARTIFACT_MISSING', spec.artifact_id, f'{spec.path}: declared artifact does not exist'))
            continue
        try:
            digest, size = (hash_file(path), path.stat().st_size)
        except OSError as exc:
            problems.append(('ARTIFACT_HASH_FAILED', spec.artifact_id, f'{spec.path}: {type(exc).__name__}: {exc}'))
            continue
        missing = [d for d in spec.derived_from if d not in by_id]
        if missing:
            problems.append(('EVIDENCE_ARTIFACT_UNKNOWN', spec.artifact_id, f'{spec.artifact_id} is derived from unknown artifacts {missing}'))
            continue
        origins = {by_id[d].origin_capture_context for d in spec.derived_from if by_id[d].origin_capture_context}
        origin = sorted(origins)[0] if len(origins) == 1 else None if origins else execution_context
        if len(origins) > 1:
            problems.append(('EVIDENCE_CONTEXT_INCOMPATIBLE', spec.artifact_id, f'{spec.artifact_id} derives from artifacts captured in different contexts {sorted(origins)}; a single derived artifact cannot claim both'))
            continue
        artifact = Artifact(artifact_id=spec.artifact_id, kind=spec.kind, path=_relative(root, path), absolute_path=str(path), sha256=digest, bytes=size, media_type=spec.media_type, description=spec.description, classification=DERIVED if spec.derived_from else CANONICAL, derived_from=tuple(spec.derived_from), origin_capture_context=origin, created_by_request=request_id, complete=bool(spec.complete) and complete)
        by_id[artifact.artifact_id] = artifact
        out.append(artifact)
    return (out, problems)

