def run_process(spec, scopes, clock=time.monotonic):
    """Execute an authorized spec. Returns a ProcessOutcome; raises ProcessSpecError for a bad spec.

    Never raises for a failing, hanging or noisy process: those are outcomes, not exceptions.
    """
    validate_spec(spec, scopes)
    started = clock()
    popen_kwargs = {'cwd': spec.cwd, 'env': spec.env.build(), 'stdin': subprocess.DEVNULL, 'stdout': subprocess.PIPE, 'stderr': subprocess.PIPE, 'close_fds': True}
    if os.name == 'posix':
        popen_kwargs['start_new_session'] = True
    try:
        proc = subprocess.Popen([spec.executable] + list(spec.argv), **popen_kwargs)
    except (FileNotFoundError, PermissionError, NotADirectoryError, IsADirectoryError) as exc:
        raise ProcessSpecError('TOOL_NOT_FOUND', f'{spec.executable}: {type(exc).__name__}: {exc}') from exc
    except OSError as exc:
        raise ProcessSpecError('EXECUTION_FAILED', f'{spec.executable}: the process could not be started ({type(exc).__name__}: {exc})') from exc
    sinks = ({'data': bytearray(), 'total': 0}, {'data': bytearray(), 'total': 0})
    readers = [threading.Thread(target=_drain, args=(s, spec.capture_bytes, sink), daemon=True) for s, sink in ((proc.stdout, sinks[0]), (proc.stderr, sinks[1]))]
    for r in readers:
        r.start()
    timed_out = terminated = False
    try:
        proc.wait(timeout=spec.timeout)
    except subprocess.TimeoutExpired:
        timed_out = terminated = True
        _terminate(proc)
    for r in readers:
        r.join(timeout=5.0)
    duration = clock() - started
    raw_out, raw_err = (bytes(sinks[0]['data']), bytes(sinks[1]['data']))
    out, out_n = redact(raw_out.decode('utf-8', errors='replace'))
    err, err_n = redact(raw_err.decode('utf-8', errors='replace'))
    return ProcessOutcome(exit_code=None if timed_out else proc.returncode, stdout=out, stderr=err, stdout_bytes=sinks[0]['total'], stderr_bytes=sinks[1]['total'], stdout_truncated=sinks[0]['total'] > len(sinks[0]['data']), stderr_truncated=sinks[1]['total'] > len(sinks[1]['data']), timed_out=timed_out, terminated=terminated, duration_seconds=round(duration, 6), redactions=out_n + err_n, raw_stdout=raw_out, raw_stderr=raw_err)
